-- Metadata-only audit, 2026-10-29. Preserve existing complete fields.
-- Shows have no tags column: discovery tags are derived from episode text[].
-- Exoria author remains unresolved: no reliable author credit in source material.
begin;
create temporary table metadata_content_hashes on commit drop as
 select 'episodes' kind,id,md5(transcript::text) hash from episodes
 union all select 'chapters',id,md5(content::text) from chapters;
update public.shows set description='Arabic-dubbed Arcane drama about Violet and Jinx, a failed rescue, and the strain between sisters.' where slug='arc' and nullif(trim(description),'') is null;
update public.shows set description='Arabic-dubbed Breaking Bad drama featuring Walter and Skyler confronting danger, power, and the consequences of his criminal business.' where slug='bb' and nullif(trim(description),'') is null;
update public.shows set description='Arabic-dubbed Mobland crime drama about Harry, a hidden body, police questioning, and suspicion over who revealed the truth.' where slug='mob' and nullif(trim(description),'') is null;
update public.shows set description='Arabic-dubbed cinema scenes featuring Don Corleone, family loyalties, business negotiations, revenge, and uneasy peace.' where slug='mov' and nullif(trim(description),'') is null;
update public.shows set description='Arabic-dubbed Prison Break scenes featuring Michael Scofield, Dr Sara Tancredi, and conversations inside the prison.' where slug='pb' and nullif(trim(description),'') is null;
update public.episodes set description=case when nullif(trim(description),'') is null then 'Violet confronts Jinx after her attempt to help goes wrong, ending in an anguished argument between the sisters.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Drama','Family','Emotions','Argument']::text[] else tags end where slug='arc-1' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Skyler fears for Walt''s safety, but he insists that his power over a criminal business makes him the danger.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Drama','Family','Coercion','Dialogue']::text[] else tags end where slug='bb-1' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Zayd faces a plan to escape execution, knowing that his guarantor Abu Dharr could bear the consequences.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Islamic History','Justice','Family','Responsibilities']::text[] else tags end where slug='cop-2' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Mark confronts his father over lies and betrayal, rejecting his attempt to explain a painful mistake.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Superhero','Family','Trust','Regret']::text[] else tags end where slug='inv-21' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Mark is urged to fight like a Viltrumite as he struggles to defend others without killing.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Superhero','Action','Humanity','Responsibilities']::text[] else tags end where slug='inv-22' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'A Viltrumite warrior is accused of becoming weak and disloyal after his time on Earth.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Superhero','Identity','Humanity','Coercion']::text[] else tags end where slug='inv-23' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Anissa threatens a girl to force Mark into a private conversation about Viltrum.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Superhero','Coercion','Rescue','Dialogue']::text[] else tags end where slug='inv-24' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Anissa demands Mark''s obedience while he is urged to pretend that he will take control of Earth.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Superhero','Action','Coercion','Responsibilities']::text[] else tags end where slug='inv-25' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Woody calls on Buzz Lightyear to rescue Bo in a playful adventure celebrating teamwork.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Cartoon','Adventure','Rescue','Teamwork']::text[] else tags end where slug='misc-27' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'A determined volleyball player faces doubts about his height and ability while dreaming of team victories.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Anime','Ambition','Competition','Teamwork']::text[] else tags end where slug='misc-28' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'A concealed body and a rapid police summons fuel suspicion, while one man insists that Harry is not responsible.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Drama','Mystery','Trust','Dialogue']::text[] else tags end where slug='mob-1' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Don Corleone weighs political influence, family loyalties, and financial risk before rejecting Sollozzo''s proposal.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Drama','Family','Work','Dialogue']::text[] else tags end where slug='mov-1' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'After both families lose sons, Don Corleone argues against revenge and pledges to preserve a negotiated peace.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Drama','Family','Promises','Dialogue']::text[] else tags end where slug='mov-2' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Umar hears verses from Surah Ta Ha, learns of the Prophet''s supplication, and asks to meet him and his companions.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Islamic History','Omar ibn Al-Khattab','Faith','Prayer']::text[] else tags end where slug='oma5-5' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'Michael Scofield meets Dr Sara Tancredi in prison, discussing his medical report, her family, and making a difference.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Drama','Dialogue','Identity','Work']::text[] else tags end where slug='pb-1' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'A worker returns for unpaid wages and discovers that his employer has invested them for him; the sincere deed helps move the cave''s boulder.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Islamic History','Faith','Honesty','Work','Cave']::text[] else tags end where slug='qss-11' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'A man who has killed ninety-nine people seeks repentance, but an unlearned monk wrongly tells him there is no hope.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Islamic History','Repentance','Faith','Wisdom']::text[] else tags end where slug='qss-12' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.episodes set description=case when nullif(trim(description),'') is null then 'A scholar reassures a repentant killer of Allah''s forgiveness and advises him to leave his troubled past behind.' else description end,tags=case when coalesce(cardinality(tags),0)=0 then array['Islamic History','Repentance','Faith','Wisdom']::text[] else tags end where slug='qss-13' and (nullif(trim(description),'') is null or coalesce(cardinality(tags),0)=0);
update public.books set title_ar='???? ????' where slug='mar' and nullif(trim(title_ar),'') is null;
do $$ begin
 if exists(select 1 from metadata_content_hashes h join episodes e on e.id=h.id where h.kind='episodes' and h.hash is distinct from md5(e.transcript::text))
 or exists(select 1 from metadata_content_hashes h join chapters c on c.id=h.id where h.kind='chapters' and h.hash is distinct from md5(c.content::text))
 then raise exception 'Content JSON changed during metadata-only update'; end if;
end $$;
commit;
